return [
  {
    json: {
      message_nada_econtrado:
        "❌ Cidade não encontrada. Use o formato Cidade,UF (ex.: São Paulo,SP).",
    },
  },
];

const cidade = $input.first().json.name
const temperatura = $input.first().json.main.temp

// Arredondar apenas se necessário
const temperaturaFinal = Number.isInteger(temperatura)
  ? temperatura
  : Math.round(temperatura);

// Criar string final
const mensagemFinal = `🌤️ A temperatura em ${cidade} é de ${temperaturaFinal}°C`;

return [
  {
    json: {
      cidade,
      temperaturaOriginal: temperatura,
      temperaturaArredondada: temperaturaFinal,
      mensagem_final: mensagemFinal
    }
  }
];

let input = $input.first().json.queue|| "";

// 1. Remove espaços extras
input = input.trim().replace(/\s+/g, " ");

// 2. Remove apóstrofos (normal e tipográfico)
input = input.replace(/[’']/g, "");

// 3. Remove espaços extras novamente (caso tenha criado espaços duplos)
input = input.trim().replace(/\s+/g, " ");

let cidade = "";
let estado = "";
let pais = "BR"; // padrão

// 4. Se usar vírgula → prioriza formato oficial
if (input.includes(",")) {

    let partes = input.split(",").map(p => p.trim());

    cidade = partes[0];

    if (partes[1] && partes[1].length === 2) {
        estado = partes[1].toUpperCase();
    }

    if (partes[2] && partes[2].length === 2) {
        pais = partes[2].toUpperCase();
    }

} else {

    let partes = input.split(" ");

    if (partes.length > 1 && /^[a-zA-Z]{2}$/.test(partes[partes.length - 1])) {
        pais = partes.pop().toUpperCase();
    }

    if (partes.length > 1 && /^[a-zA-Z]{2}$/.test(partes[partes.length - 1])) {
        estado = partes.pop().toUpperCase();
    }

    cidade = partes.join(" ");
}

// 5. Ajusta capitalização mantendo acento
cidade = cidade
    .toLowerCase()
    .split(" ")
    .map(p => p.charAt(0).toUpperCase() + p.slice(1))
    .join(" ");

// 6. Monta query final
let queryFinal = estado 
    ? `${cidade},${estado},${pais}`
    : `${cidade},${pais}`;

// 7. Encode para URL
let queryEncoded = encodeURIComponent(queryFinal);

return [
  {
    json: {
      cidade_formatada: queryFinal,
      cidade_url: queryEncoded
    }
  }
];

// Pre-Flight Check: Validação de Integridade e Configuração
const input = $input.first().json;

// 1. Verificação de Entrada do Telegram
const hasText = input.message && input.message.text;
const chatId = input.message?.chat?.id;

// 2. Simulação de Check de Credenciais (Best Practice Sênior)
// Em ambientes de produção, checamos se as variáveis essenciais estão presentes
const config = {
  hasTelegramToken: !!chatId, // Se recebemos o webhook, o token do Telegram está ok
  // Adicione aqui verificações de variáveis de ambiente se estiver usando-as
};

const errors = [];

if (!hasText) {
  errors.push("Mensagem de texto ausente ou formato inválido.");
}

if (!config.hasTelegramToken) {
  errors.push("Falha crítica: Identificador de chat não encontrado.");
}

// 3. Resultado da Verificação
return [
  {
    json: {
      status: errors.length === 0 ? "success" : "error",
      error_details: errors.join(" | "),
      timestamp: new Date().toISOString(),
      // Passa os dados originais adiante para não quebrar o fluxo
      ...input 
    }
  }
];
